-- Milestone 5: ad accounts, campaigns, daily ad metrics, daily aggregates
CREATE TABLE "AdAccount" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "integrationId" TEXT, "platform" TEXT NOT NULL, "sourceType" TEXT NOT NULL DEFAULT 'api', "externalId" TEXT, "name" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'BDT', "status" TEXT NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AdAccount_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AdAccount_organizationId_platform_externalId_key" ON "AdAccount"("organizationId","platform","externalId");
CREATE INDEX "AdAccount_organizationId_platform_idx" ON "AdAccount"("organizationId","platform");
CREATE TABLE "AdCampaign" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "adAccountId" TEXT NOT NULL, "externalId" TEXT NOT NULL, "name" TEXT NOT NULL, "objective" TEXT, "status" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AdCampaign_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AdCampaign_adAccountId_externalId_key" ON "AdCampaign"("adAccountId","externalId");
CREATE INDEX "AdCampaign_organizationId_idx" ON "AdCampaign"("organizationId");
CREATE TABLE "DailyAdMetric" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "adAccountId" TEXT NOT NULL, "adCampaignId" TEXT, "platform" TEXT NOT NULL, "source" TEXT NOT NULL, "campaignExternalId" TEXT NOT NULL DEFAULT '', "campaignName" TEXT, "date" TIMESTAMP(3) NOT NULL, "currency" TEXT NOT NULL DEFAULT 'BDT', "spendMinor" BIGINT NOT NULL DEFAULT 0, "impressions" INTEGER NOT NULL DEFAULT 0, "clicks" INTEGER NOT NULL DEFAULT 0, "platformConversions" INTEGER NOT NULL DEFAULT 0, "platformConversionValueMinor" BIGINT NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DailyAdMetric_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DailyAdMetric_organizationId_adAccountId_campaignExternalId_date_source_key" ON "DailyAdMetric"("organizationId","adAccountId","campaignExternalId","date","source");
CREATE INDEX "DailyAdMetric_organizationId_date_idx" ON "DailyAdMetric"("organizationId","date");
CREATE INDEX "DailyAdMetric_organizationId_platform_date_idx" ON "DailyAdMetric"("organizationId","platform","date");
CREATE TABLE "DailyMetricAggregate" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "date" TIMESTAMP(3) NOT NULL, "orders" INTEGER NOT NULL DEFAULT 0, "revenueMinor" BIGINT NOT NULL DEFAULT 0, "refundedMinor" BIGINT NOT NULL DEFAULT 0, "cogsMinor" BIGINT NOT NULL DEFAULT 0, "cogsKnownOrders" INTEGER NOT NULL DEFAULT 0, "adSpendMinor" BIGINT NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DailyMetricAggregate_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DailyMetricAggregate_organizationId_date_key" ON "DailyMetricAggregate"("organizationId","date");
CREATE INDEX "DailyMetricAggregate_organizationId_date_idx" ON "DailyMetricAggregate"("organizationId","date");
ALTER TABLE "AdAccount" ADD CONSTRAINT "AdAccount_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AdCampaign" ADD CONSTRAINT "AdCampaign_adAccountId_fkey" FOREIGN KEY ("adAccountId") REFERENCES "AdAccount"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DailyAdMetric" ADD CONSTRAINT "DailyAdMetric_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DailyAdMetric" ADD CONSTRAINT "DailyAdMetric_adAccountId_fkey" FOREIGN KEY ("adAccountId") REFERENCES "AdAccount"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DailyAdMetric" ADD CONSTRAINT "DailyAdMetric_adCampaignId_fkey" FOREIGN KEY ("adCampaignId") REFERENCES "AdCampaign"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "DailyMetricAggregate" ADD CONSTRAINT "DailyMetricAggregate_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
